package org.springframework.cache.interceptor; import java.lang.reflect.Method; import java.util.Arrays; import org.jspecify.annotations.Nullable;
import org.springframework.core.KotlinDetector;

/**
 * Simple key generator. Returns the parameter itself if a single non-null
 * value is given, otherwise returns a {@link SimpleKey} of the parameters.
 *
 * <p>No collisions will occur with the keys generated by this class.
 * The returned {@link SimpleKey} object can be safely used with a
 * {@link org.springframework.cache.concurrent.ConcurrentMapCache}, however,
 * might not be suitable for all {@link org.springframework.cache.Cache}
 * implementations.
 *
 * @author Phillip Webb
 * @author Juergen Hoeller
 * @author Sebastien Deleuze
 * @since 4.0
 * @see SimpleKey
 * @see org.springframework.cache.annotation.CachingConfigurer
 */
public class SimpleKeyGenerator implements KeyGenerator { @Override
	public Object generate(Object target, Method method, @Nullable Object... params) {
		return generateKey((KotlinDetector.isSuspendingFunction(method) ?
				Arrays.copyOf(params, params.length - 1) : params));
	}

	/**
	 * Generate a key based on the specified parameters.
	 */
	public static Object generateKey(@Nullable Object... params) {
		if (params.length == 0) { return SimpleKey.EMPTY;
		} if (params.length == 1) {
			Object param = params[0];
			if (param != null && !param.getClass().isArray()) {
				return param; } } return new SimpleKey(params); }

}
